"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple

def _check(shifts: List) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker")

def _tally(shifts: List) -> Dict[str, Tuple[int, int]]:
    totals = {}
    for shift in shifts:
        count, mins = totals.get(shift.worker, (0, 0))
        total = mins + shift.span.minutes
        totals[shift.worker] = (count + 1, total)
    return totals

def _line(name: str, count: int, minutes: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    hours = minutes / 60
    return f"{name}: {count} {noun}, {hours:.1f} hours"

def _busiest_first(item: Tuple[str, Tuple[int, int]]):
    name, (count, minutes) = item
    return (-minutes, -count, name)

# ---
def timesheet_rows(shifts: Iterable) -> List[str]:
    """One line per worker, busiest first."""
    shifts = list(shifts)
    _check(shifts)
    tally = _tally(shifts)
    items = sorted(tally.items(), key=_busiest_first)
    return [_line(n, c, m) for n, (c, m) in items]

