# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows

def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))

class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Odell", "mon", 540, 600),
            shift("Brisa", "mon", 540, 1020),
            shift("Odell", "tue", 540, 600)
        ])
        self.assertEqual(rows, [
            "Brisa: 1 shift, 8.0 hours",
            "Odell: 2 shifts, 2.0 hours"
        ])

    def test_one_decimal(self):
        one = [shift("Quill", "wed", 0, 100)]
        rows = timesheet_rows(one)
        want = ["Quill: 1 shift, 1.7 hours"]
        self.assertEqual(rows, want)

    def test_ties_by_name(self):
        rows = timesheet_rows([
            shift("Zed", "mon", 0, 60),
            shift("Amy", "tue", 0, 60)
        ])
        self.assertTrue(rows[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([shift("  ", "mon", 0, 60)])
